import functools
from typing import ForwardRef
from fastapi.dependencies import utils

def test_wrapped_method_type_inference():
    def outer():
        class MyClass:
            pass

        def method(self, a: "MyClass"):
            pass

        @functools.wraps(method)
        def wrapped(self, a: "MyClass"):
            return method(self, a)

        return wrapped

    wrapped_func = outer()
    try:
