import asyncio
import inspect
from functools import wraps, partial
from fastapi.dependencies.models import Dependant

async def async_func():
    return "async_func"

def sync_wrapper(f):
    @wraps(f)
    def wrapper(*args, **kwargs):
        return f(*args, **kwargs)
    return wrapper

def async_wrapper(f):
    @wraps(f)
    async def wrapper(*args, **kwargs):
        return await f(*args, **kwargs)
    return wrapper

def test_combinations():
    cases = [
        ("async_func", async_func, True),
        ("sync_wrapper(async_func)", sync_wrapper(async_func), True),
        ("async_wrapper(sync_func)", async_wrapper(lambda: "sync"), True),
        ("sync_wrapper(sync_func)", sync_wrapper(lambda: "sync"), False),
        ("partial(async_func)", partial(async_func), True),
        ("partial(sync_wrapper(async_func))", partial(sync_wrapper(async_func)), True),
        ("sync_wrapper(partial(async_func))", sync_wrapper(partial(async_func)), True),
        ("partial(async_wrapper(sync_func))", partial(async_wrapper(lambda: "sync")), True),
    ]

    for name, call, expected in cases:
        dep = Dependant(call=call)
        result = dep.is_coroutine_callable
        print(f"{name}: expected {expected}, got {result}")
        assert result == expected, f"Failed {name}: expected {expected}, got {result}"

if __name__ == "__main__":
    try:
        test_combinations()
        print("All tests passed!")
    except AssertionError as e:
        print(f"Assertion failed: {e}")
    except Exception as e:
        print(f"An error occurred: {e}")

